(1, 'Samsung Galaxy S24 Ultra', 'Latest 5G smartphone with 6.8 inch Dynamic AMOLED 2X display, 200MP camera, 12GB RAM, and 256GB storage. Features advanced AI processing and all-day 5000mAh battery.', 'Smartphones', 'Samsung', '74999.00', 74, '/static/images/products/samsung_galaxy_s24_ultra.png', '4.50', '2026-08-07 20:02:59'),
(2, 'Apple MacBook Air M3', 'Ultra-thin 15 inch Liquid Retina display laptop with Apple M3 chip, 16GB unified memory, 512GB SSD, and 18-hour battery life. Perfect for professionals and creators.', 'Laptops', 'Apple', '134900.00', 16, '/static/images/products/apple_macbook_air_m3.png', '4.80', '2026-08-07 20:02:59'),
(3, 'Sony WF-1000XM5', 'Premium wireless earbuds with industry-leading noise cancellation, LDAC Hi-Res Audio, 24-hour battery life with case, and IPX4 water resistance. Crystal clear call quality.', 'Audio', 'Sony', '19990.00', 179, '/static/images/products/sony_wf_1000xm5.png', '4.20', '2026-08-07 20:02:59'),
(4, 'Apple Watch Series 9', 'Advanced smartwatch with Always-On Retina LTPO OLED display, blood oxygen monitoring, ECG, crash detection, 18-hour battery life, and 100+ workout modes.', 'Wearables', 'Apple', '41900.00', 128, '/static/images/products/apple_watch_series_9.png', '4.30', '2026-08-07 20:02:59'),
(5, 'Apple iPad Air M2', '11 inch premium tablet with Apple M2 chip, 8GB RAM, 128GB storage, quad speakers, Apple Pencil Pro support, and 60Hz Liquid Retina display.', 'Tablets', 'Apple', '59900.00', 53, '/static/images/products/apple_ipad_air_m2.png', '4.60', '2026-08-07 20:02:59'),
